"""Painel HTML autônomo das defasagens de Granger, DLM e SARIMAX."""
from __future__ import annotations

import json
from pathlib import Path

import pandas as pd

ROOT = Path(__file__).resolve().parents[1]
OUTPUT = ROOT / "outputs/reports/defasagens_metodos.html"


def run():
    g = pd.read_csv(ROOT / "outputs/tables/revisao_estadual_20261019/granger_aplicacoes.csv", encoding="utf-8-sig")
    d = pd.read_csv(ROOT / "outputs/tables/revisao_defasagens_20261024/dlm_dois_menores_aic.csv", encoding="utf-8-sig")
    s = pd.read_csv(ROOT / "outputs/tables/sarimax_defasagens_20261024/comparacao.csv", encoding="utf-8-sig")
    inf = pd.read_csv(ROOT / "outputs/tables/revisao_defasagens_20261024/dlm_inferencia_top2.csv", encoding="utf-8-sig")
    assert len(g) == 864 and len(d) == 29 and len(s) == 54
    gs = g[g.status.eq("estimado")].copy()
    assert gs.p_lags.between(1, 6).all()
    granger = [{"uf": x.uf, "periodo": x.periodo, "tipo": x.tipologia.removeprefix("tipo_"),
                "lag": int(x.p_lags), "bh": bool(x.rejeicao_bh)} for x in gs.itertuples(index=False)]
    dlm = [{"periodo": x.periodo, "tipo": x.tipologia.removeprefix("tipo_"),
            "k1": int(x.K_menor_AIC), "k2": int(x.K_segundo_AIC),
            "delta": round(x.delta_AIC, 4), "aic1": round(x.AIC_1, 4),
            "aic2": round(x.AIC_2, 4), "w1": round(x.peso_Akaike_1, 4),
            "w2": round(x.peso_Akaike_2, 4)} for x in d.itertuples(index=False)]
    sarimax = [{"uf": x.unidade, "periodo": x.periodo, "status": x.status,
               "lag": str(x.lag_escolhido) if pd.notna(x.lag_escolhido) else None,
               "tipos": int(x.n_tipologias_elegiveis),
               "delta": round(x.delta_BIC, 3) if pd.notna(x.delta_BIC) else None,
               "rmse": round(x.melhora_rmse_pct, 2) if pd.notna(x.melhora_rmse_pct) else None}
              for x in s.itertuples(index=False)]
    counts = inf.groupby(["posicao_AIC", "banda_DK"]).rejeicao_apos_ajustes.sum().to_dict()
    stats = {"granger_total": len(g), "granger_estimaveis": len(granger),
             "granger_bh": sum(x["bh"] for x in granger), "dlm": len(dlm),
             "dlm_delta2": int(d.delta_AIC.lt(2).sum()), "sarimax": len(sarimax),
             "sarimax_validos": int(s.status.eq("estimado").sum()),
             "sarimax_bic": int(s.delta_BIC.lt(0).sum()),
             "dk1": [int(counts.get((1, f), 0)) for f in ("dk_regra", "dk6", "dk12")],
             "dk2": [int(counts.get((2, f), 0)) for f in ("dk_regra", "dk6", "dk12")]}
    payload = {"granger": granger, "dlm": dlm, "sarimax": sarimax, "stats": stats}
    data = json.dumps(payload, ensure_ascii=False, separators=(",", ":")).replace("</", "<\\/")
    template = r'''<!doctype html><html lang="pt-BR"><head><meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<meta name="theme-color" content="#813a65"><title>Defasagens | Mudanças Climáticas e Inadimplência</title>
<link rel="icon" href="data:image/svg+xml,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 64 64'%3E%3Crect width='64' height='64' rx='16' fill='%23813a65'/%3E%3Cpath d='M16 42V25m16 17V17m16 25V30' stroke='white' stroke-width='7' stroke-linecap='round'/%3E%3C/svg%3E">
<style>*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:#f8f8fa;color:#292b34;font:14px/1.5 Inter,system-ui,-apple-system,Segoe UI,sans-serif}a{color:inherit}header{background:#fcfbfd;border-bottom:1px solid #eae4eb}header .inner{max-width:1180px;margin:auto;padding:38px 24px 32px}h1{font-size:clamp(30px,4.5vw,52px);line-height:1.07;margin:12px 0 18px;letter-spacing:-.055em;max-width:850px}header p{color:#777785;max-width:780px;font-size:15px}small{color:#7c7d88}.eyebrow{font-weight:750;font-size:11px;letter-spacing:.16em;text-transform:uppercase;color:#994c7d}main{max-width:1180px;padding:26px 24px 80px;margin:auto}nav{display:flex;gap:8px;flex-wrap:wrap;margin:0 0 28px}.tab{border:1px solid #e6e1e8;background:white;color:#525563;padding:11px 18px;border-radius:50px;cursor:pointer;font:inherit}.tab.on{background:#813a65;color:white;border-color:#813a65}.grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px}.card,.panel{background:white;border:1px solid #e9e6ec;border-radius:16px;padding:21px;box-shadow:0 2px 8px #25212a05}.card .big{font-size:29px;letter-spacing:-.04em;font-weight:750}.card .small{font-size:12px;color:#8a8993;margin-top:5px}h2{font-size:25px;letter-spacing:-.035em;margin:0 0 9px}.lead{color:#727581;max-width:850px;margin:0 0 22px}.panel{margin:18px 0 23px}h3{margin:0 0 8px;font-size:16px}.note{border-left:3px solid #a55988;padding:7px 17px;background:#fbf6fa;border-radius:0 9px 9px 0;color:#685e69;margin:18px 0 24px}.filters{display:flex;align-items:center;gap:12px;flex-wrap:wrap;margin:0 0 20px}select{padding:9px 13px;border:1px solid #dddce2;border-radius:9px;min-width:125px;background:white;color:#333;font:inherit}.stack{display:flex;height:24px;border-radius:8px;overflow:hidden;background:#f2f3f5;margin:14px 0 10px}.piece{height:100%;transition:width .25s}.legend{display:flex;flex-wrap:wrap;gap:14px;font-size:12px;color:#6f7280}.legend span i{display:inline-block;width:9px;height:9px;border-radius:2px;margin-right:5px}.tablewrap{overflow:auto}table{border-collapse:collapse;min-width:720px;width:100%;font-size:12.5px}td,th{text-align:right;padding:11px 12px;border-bottom:1px solid #edebf0;white-space:nowrap}td:nth-child(-n+2),th:nth-child(-n+2){text-align:left}th{font-size:10px;text-transform:uppercase;letter-spacing:.08em;color:#898797}tbody tr:hover{background:#fdf9fc}.pill{display:inline-block;padding:4px 9px;border-radius:14px;background:#f7edf4;color:#874669;font-weight:650}.good{color:#337a6a}.bad{color:#9c5b6a}.hidden{display:none!important}.muted{color:#777985}.barrow{display:flex;gap:12px;align-items:center;margin:10px 0}.barrow b{min-width:110px}footer{border-top:1px solid #e6e1e9;padding-top:23px;margin-top:45px;color:#7c7a86;font-size:12px}@media(max-width:760px){main{padding:22px 12px 70px}.grid{grid-template-columns:repeat(2,1fr)}header .inner{padding:34px 16px}.card,.panel{padding:14px}.card .big{font-size:24px}}@media print{nav,.filters{display:none}section{display:block!important;page-break-inside:avoid}body{background:white}.panel{box-shadow:none}}</style></head>
<body><header><div class="inner"><div class="eyebrow">TCC · Isabella Viana Bambirra · Resultados complementares</div><h1>O que as defasagens mostram em cada método?</h1><p>Uma visualização dos horizontes escolhidos em Granger, DLM e SARIMAX para as 16 tipologias de desastres climáticos, nas 27 UFs e em dois períodos.</p></div></header>
<main><nav aria-label="Etapas"><button class="tab on" data-tab="resumo">Visão geral</button><button class="tab" data-tab="granger">Granger</button><button class="tab" data-tab="dlm">DLM · AIC</button><button class="tab" data-tab="sarimax">SARIMAX</button></nav>
<section id="resumo"><div class="grid"><div class="card"><div class="eyebrow">Granger</div><div class="big" id="grangerNum"></div><div class="small">testes estimáveis de 864</div></div><div class="card"><div class="eyebrow">DLM</div><div class="big" id="dlmNum"></div><div class="small">combinações com ΔAIC &lt; 2</div></div><div class="card"><div class="eyebrow">SARIMAX</div><div class="big" id="sarNum"></div><div class="small">comparações estimadas de 54</div></div><div class="card"><div class="eyebrow">SARIMAX × SARIMA</div><div class="big" id="bicNum"></div><div class="small">melhoras de BIC</div></div></div>
<div class="panel"><h2>Três perguntas diferentes</h2><p class="lead">Os números de meses não são diretamente comparáveis: cada método define e escolhe a defasagem de forma distinta.</p><div class="grid" style="grid-template-columns:repeat(auto-fit,minmax(220px,1fr))"><div><h3>Granger</h3><p class="muted">Quantos meses passados de cada série entram no teste de precedência preditiva? A grade é de 1 a 6 meses por UF, período e tipologia.</p></div><div><h3>DLM</h3><p class="muted">Até qual horizonte K são incluídos, juntos, os coeficientes contemporâneo e defasados? Grade de K=1 a 24 pelo AIC.</p></div><div><h3>SARIMAX</h3><p class="muted">Qual bloco de exposições exógenas melhora o critério BIC no treino? Comparamos [0], [0,1] e [0,1,3], com tipologias elegíveis simultâneas.</p></div></div></div>
<div class="panel"><h2>O que permanece após a inferência do DLM?</h2><p class="lead">Número de hipóteses rejeitadas após a proteção pela busca de K e ajuste de Holm entre as 16 tipologias, por período e hipótese.</p><div class="tablewrap"><table><thead><tr><th>AIC</th><th>DK por regra</th><th>DK6</th><th>DK12</th></tr></thead><tbody id="dkSummary"></tbody></table></div><div class="note">O DK modifica os erros-padrão, não os coeficientes nem o AIC. Os resultados dependentes de bandas maiores devem ser lidos como sensibilidade, não como evidência robusta sob todas as escolhas.</div></div></section>
<section id="granger" class="hidden"><h2>Granger · seleção por BIC</h2><p class="lead">Distribuição das defasagens selecionadas (1 a 6 meses) entre os testes estimáveis. Use os filtros para examinar uma UF ou tipologia.</p><div class="filters"><label>Período <select id="gPeriod"><option value="todos">Ambos</option><option>Pré</option><option>Total</option></select></label><label>UF <select id="gUf"><option value="todos">Todas</option></select></label><label>Tipologia <select id="gTip"><option value="todos">Todas</option></select></label></div><div class="panel"><h3 id="gN"></h3><div id="gStack" class="stack"></div><div id="gLegend" class="legend"></div></div><div class="panel"><h3>Detalhamento</h3><div class="tablewrap"><table><thead><tr><th>Período</th><th>UF</th><th>Tipologia</th><th>p pelo BIC</th><th>Teste BH</th></tr></thead><tbody id="gRows"></tbody></table></div></div></section>
<section id="dlm" class="hidden"><h2>DLM · primeira e segunda escolha por AIC</h2><p class="lead">Os dois menores AICs descrevem alternativas próximas na grade. Como os modelos são aninhados e usam a mesma amostra, um candidato K+1 fica automaticamente até 2 unidades acima do AIC(K) escolhido quando K&lt;24.</p><div class="filters"><label>Período <select id="dPeriod"><option value="todos">Ambos</option><option>Pré</option><option>Total</option></select></label></div><div class="panel"><div class="tablewrap"><table><thead><tr><th>Período</th><th>Tipologia</th><th>1º K</th><th>2º K</th><th>1º AIC</th><th>2º AIC</th><th>ΔAIC</th><th>Peso 1º</th><th>Peso 2º</th></tr></thead><tbody id="dRows"></tbody></table></div></div><div class="note">ΔAIC pequeno é parcialmente mecânico na comparação aninhada e não indica significância dos coeficientes. Os pesos de Akaike incluem toda a grade; o segundo K representa sensibilidade de especificação, não um efeito independente.</div></section>
<section id="sarimax" class="hidden"><h2>SARIMAX · blocos de defasagens</h2><p class="lead">Cada aplicação usa a mesma amostra de treino/teste entre as três estruturas e uma ordem SARIMA comum, escolhida pelo BIC do treino.</p><div class="filters"><label>Período <select id="sPeriod"><option value="todos">Ambos</option><option>Pré</option><option>Total</option></select></label></div><div class="panel"><h3>Seleção climática por BIC</h3><p id="sSelection" class="muted"></p><div class="barrow"><b>Lag 0</b><div class="stack" style="flex:1;margin:0"><div class="piece" id="sLagBar" style="background:#a85b88"></div></div><span id="sLagPct"></span></div><p class="muted">As 16 tipologias são auditadas como candidatas, mas categorias sem suporte ou posto suficiente são removidas antes do ajuste. A previsão com lag 0 utiliza informação climática observada no próprio mês.</p></div><div class="panel"><div class="tablewrap"><table><thead><tr><th>Período</th><th>UF</th><th>Tipologias</th><th>Estrutura BIC</th><th>ΔBIC vs SARIMA</th><th>Ganho RMSE</th><th>Status</th></tr></thead><tbody id="sRows"></tbody></table></div></div></section>
<footer>Base mensal: 2013–2024 · 27 UFs · 16 tipologias · Pré-pandemia até janeiro de 2020 · Resultados auditados em 24/10/2026. AIC/BIC medem ajuste penalizado, não causalidade. Testes selecionados permanecem exploratórios.</footer></main>
<script>const DATA=__EMBEDDED_DATA__;
const $=id=>document.getElementById(id);const pretty=t=>t.replaceAll('_',' ').replace(/\b\w/g,c=>c.toUpperCase());const num=(v,n=2)=>v==null?'—':Number(v).toLocaleString('pt-BR',{minimumFractionDigits:n,maximumFractionDigits:n});
document.querySelectorAll('.tab').forEach(b=>b.onclick=()=>{document.querySelectorAll('.tab').forEach(x=>x.classList.toggle('on',x===b));document.querySelectorAll('main section').forEach(x=>x.classList.toggle('hidden',x.id!==b.dataset.tab));});
$('grangerNum').textContent=DATA.stats.granger_estimaveis;$('dlmNum').textContent=DATA.stats.dlm_delta2+'/'+DATA.stats.dlm;$('sarNum').textContent=DATA.stats.sarimax_validos;$('bicNum').textContent=DATA.stats.sarimax_bic+'/'+DATA.stats.sarimax_validos;
$('dkSummary').innerHTML=['1º menor AIC','2º menor AIC'].map((n,i)=>'<tr><td>'+n+'</td>'+[DATA.stats.dk1,DATA.stats.dk2][i].map(v=>'<td>'+v+'</td>').join('')+'</tr>').join('');
for(const [id,values] of [['gUf',[...new Set(DATA.granger.map(x=>x.uf))].sort()],['gTip',[...new Set(DATA.granger.map(x=>x.tipo))].sort()]]){for(const val of values){const opt=document.createElement('option');opt.value=val;opt.textContent=id==='gTip'?pretty(val):val;$(id).appendChild(opt);}}
const colors=['#9c4775','#c6759d','#e5a5be','#a19bb9','#6a9aaa','#75b7a7'];
function drawGranger(){const a=DATA.granger.filter(x=>($('gPeriod').value==='todos'||x.periodo===$('gPeriod').value)&&($('gUf').value==='todos'||x.uf===$('gUf').value)&&($('gTip').value==='todos'||x.tipo===$('gTip').value));const count=[1,2,3,4,5,6].map(i=>a.filter(x=>x.lag===i).length);$('gN').textContent=a.length+' testes estimáveis';$('gStack').innerHTML=count.map((v,i)=>'<div class="piece" title="p='+ (i+1)+': '+v+'" style="width:'+(a.length?100*v/a.length:0)+'%;background:'+colors[i]+'"></div>').join('');$('gLegend').innerHTML=count.map((v,i)=>'<span><i style="background:'+colors[i]+'"></i>p='+(i+1)+': '+v+'</span>').join('');$('gRows').innerHTML=a.map(x=>'<tr><td>'+x.periodo+'</td><td>'+x.uf+'</td><td>'+pretty(x.tipo)+'</td><td><span class="pill">'+x.lag+'</span></td><td>'+(x.bh?'rejeita':'não rejeita')+'</td></tr>').join('');}
for(const id of ['gPeriod','gUf','gTip'])$(id).onchange=drawGranger;drawGranger();
function drawDlm(){const a=DATA.dlm.filter(x=>$('dPeriod').value==='todos'||x.periodo===$('dPeriod').value);$('dRows').innerHTML=a.map(x=>'<tr><td>'+x.periodo+'</td><td>'+pretty(x.tipo)+'</td><td><span class="pill">'+x.k1+'</span></td><td>'+x.k2+'</td><td>'+num(x.aic1,3)+'</td><td>'+num(x.aic2,3)+'</td><td><b>'+num(x.delta,3)+'</b></td><td>'+num(x.w1*100,1)+'%</td><td>'+num(x.w2*100,1)+'%</td></tr>').join('');} $('dPeriod').onchange=drawDlm;drawDlm();
function drawSarimax(){const a=DATA.sarimax.filter(x=>$('sPeriod').value==='todos'||x.periodo===$('sPeriod').value);const valid=a.filter(x=>x.status==='estimado');const l0=valid.filter(x=>x.lag==='l0').length;const pct=valid.length?100*l0/valid.length:0;$('sSelection').textContent=l0+' de '+valid.length+' selecionaram somente o mês contemporâneo';$('sLagBar').style.width=pct+'%';$('sLagPct').textContent=num(pct,0)+'%';$('sRows').innerHTML=a.map(x=>'<tr><td>'+x.periodo+'</td><td>'+x.uf+'</td><td>'+x.tipos+'</td><td>'+(x.lag||'—')+'</td><td>'+(x.delta==null?'—':num(x.delta))+'</td><td class="'+(x.rmse>=0?'good':'bad')+'">'+(x.rmse==null?'—':num(x.rmse)+'%')+'</td><td>'+(x.status==='estimado'?'estimado':'não estimável')+'</td></tr>').join('');} $('sPeriod').onchange=drawSarimax;drawSarimax();
</script></body></html>'''
    OUTPUT.parent.mkdir(parents=True, exist_ok=True)
    OUTPUT.write_text(template.replace("__EMBEDDED_DATA__", data), encoding="utf-8")
    print(f"HTML: {OUTPUT.relative_to(ROOT)} ({OUTPUT.stat().st_size} bytes)")


if __name__ == "__main__":
    run()
